// Cloudflare Worker: JWT validation at the edge
export default {
  async fetch(request: Request): Promise<Response> {
    const authHeader = request.headers.get('Authorization');
    if (!authHeader?.startsWith('Bearer ')) {
      return new Response('Unauthorized', { status: 401 });
    }
    const token = authHeader.slice(7);
    const isValid = await verifyJwt(token);  // edge-native crypto
    if (!isValid) {
      return new Response('Forbidden', { status: 403 });
    }
    // Only valid requests reach origin
    return fetch(request);
  }
};

// eBPF tracepoint program: count HTTP 500 responses
// (simplified; compiled with clang -target bpf)
#include <linux/bpf.h>
#include <bpf/bpf_helpers.h>

struct {
    __uint(type, BPF_MAP_TYPE_PERCPU_ARRAY);
    __uint(max_entries, 1);
    __type(key, int);
    __type(value, long);
} http5xx_count SEC(".maps");

SEC("tracepoint/net/net_dev_xmit")
int count_500(struct trace_event_raw_net_dev_xmit *ctx) {
    // inspect packet, increment counter on HTTP 5xx
    int key = 0;
    long *val = bpf_map_lookup_elem(&http5xx_count, &key);
    if (val) __sync_fetch_and_add(val, 1);
    return 0;
}

// Deno Deploy edge microservice: rate-limit by IP
import { serve } from 'https://deno.land/std@0.224.0/http/server.ts';

const kv = await Deno.openKv();  // Deno KV — globally replicated

serve(async (req: Request) => {
  const ip = req.headers.get('cf-connecting-ip') ?? 'unknown';
  const key = ['rate', ip, new Date().toISOString().slice(0, 16)];

  const { value: count } = await kv.get<number>(key);
  if ((count ?? 0) >= 100) {
    return new Response('Rate limited', { status: 429 });
  }
  await kv.atomic().sum(key, 1n).commit();
  return fetch(req);  // proxy to origin
});

// Dapr state API — no Redis SDK, no Kafka SDK
package main

import (
    dapr "github.com/dapr/go-sdk/client"
    "context"
)

func main() {
    client, _ := dapr.NewClient()
    ctx := context.Background()

    // Save state — backend is Redis or Cosmos DB per component config
    client.SaveState(ctx, "statestore", "order-123",
        []byte(`{"status":"processing"}`), nil)

    // Publish event — broker is Kafka or SQS per component config
    client.PublishEvent(ctx, "pubsub", "orders",
        []byte(`{"orderId":"123"}`))
}

# Orders subgraph — declares reference to Product entity
type Order @key(fields: "id") {
  id: ID!
  lineItems: [LineItem!]!
}

type LineItem {
  quantity: Int!
  product: Product!  # reference resolved by Products subgraph
}

# Products subgraph — owns the Product entity
type Product @key(fields: "id") {
  id: ID!
  name: String!
  price: Float!
  sustainabilityScore: Float  # added independently
}

